function main(): void {
  const e = Object.assign(new Error("m"), { a: 1, b: "two" }, { c: true }) as any;
  console.log(Object.keys(e), e.a, e.b, e.c);
  const j: any = { d: [1, 2] };
  Object.assign(e, j);
  console.log(Object.keys(e), e.d);
  console.log(Object.getOwnPropertyNames(e));
}
